const V=window.VARIATION;
const designNames=['Marketplace Index','Skills Hub','MCP Market','Technical Registry'];
const link=(r,t)=>`<a href="#/${r}">${t}</a>`;
const dropdown=(t,links)=>`<details class="nav-drop"><summary>${t}⌄</summary><div>${links.map(x=>link(...x)).join('')}</div></details>`;
const navigation=[
 [['skills','Skills'],['mcp-servers','MCP'],['marketplace','Marketplaces'],['digest','Digest'],['tools','Tools'],['advertise','Advertise'],['login','Login']],
 [['skills','Skills'],['mcp-servers','MCP'],['plugins','Plugins'],['harness','Harness'],['newsletter','Newsletter']],
 [],
 [['skills','Skills'],['mcp-servers','MCP'],['marketplace','Marketplace'],['digest','Digest'],['blog','Blog'],['learn','Learn'],['advertise','Advertise'],['login','Login']]
];
const baseShell=shell;
shell=function(){baseShell();document.body.dataset.variant=V;document.body.dataset.theme='light';$('#theme').value='light';
 $('.topbar').innerHTML=`<a class="logo" href="#/discover">${B.name}</a><nav class="ref-nav" aria-label="Main navigation">${navigation[V-1].map(x=>link(...x)).join('')}${V===2?dropdown('Learn',[['learn','Guides & tutorials'],['security-and-installation-safety','Installation guide'],['how-listings-work','Methodology']])+dropdown('More',[['categories','Categories'],['submit','Submit a resource'],['about','About'],['contact','Contact']])+link('advertise','Advertise')+link('login','Login'):''}${V===3?dropdown('MCP Servers',[['mcp-servers','All MCP servers'],['categories','Categories'],['repositories','Repositories'],['learn','What is MCP?']])+dropdown('Agent Skills',[['skills','All skills'],['categories','Categories'],['leaderboard','Top skills'],['learn','How to install']])+`<span class="nav-spacer"></span>`+link('submit','Sell Skills')+link('hub','Power Your Agents'):''}<button id="themeToggle" aria-label="Toggle color theme">☼</button></nav><details class="mobile-menu"><summary>Menu +</summary><div>${navigation[V-1].concat([['discover','Discover'],['skills','Skills'],['mcp-servers','MCP servers'],['marketplace','Marketplace'],['hub','Workspace'],['learn','Learn'],['submit','Submit'],['sitemap','All pages']]).map(x=>link(...x)).join('')}</div></details>`;
 $('#themeToggle').onclick=()=>{document.body.dataset.theme=document.body.dataset.theme==='light'?'dark':'light';$('#theme').value=document.body.dataset.theme;};
 $('.ribbon').innerHTML=`<a href="../index.html">← All eight designs</a><label>Design <select id="design" aria-label="Design variation">${designNames.map((n,i)=>`<option value="${i+1}" ${V===i+1?'selected':''}>0${i+1} · ${n}</option>`).join('')}</select></label><a id="brandSwitch" href="../${B.other}/variation-0${V}.html">${B.otherName} ↗</a><div class="controls"><label>Data <select id="mode" aria-label="Catalogue data mode"><option value="reviewed">Source samples</option><option value="demo">Fictional demos</option></select></label><label class="theme-select">Theme <select id="theme" aria-label="Color theme"><option>light</option><option>dark</option><option>contrast</option></select></label></div><a href="#/saved">Saved <span id="savedCount"></span></a>`;
 $('#design').onchange=e=>location.href='variation-0'+e.target.value+'.html'+location.hash;$('#brandSwitch').onclick=e=>e.currentTarget.href='../'+B.other+'/variation-0'+V+'.html';$('#theme').onchange=e=>document.body.dataset.theme=e.target.value;$('#mode').onchange=e=>{state.mode=e.target.value;resetFilters();state.compare=[];render();};
 if(V===3)$('.topbar').insertAdjacentHTML('beforebegin','<div class="announcement">NEW · '+B.name+' Hub — Organize the tools your agents use '+link('hub','Explore →')+'</div>');
 $('.prototype').textContent='LOCAL HTML PREVIEW · Source samples and fictional demos · No live accounts, purchases or installations';
 $('.footer').insertAdjacentHTML('afterbegin',`<section class="digest-band"><div><h2>This week in ${B.id==='lawyer'?'legal technology':'AI companies'}</h2><p>Tools, workflows and infrastructure worth exploring.</p></div>${link('digest','Read the digest →')}</section>`);
};
function featured(){return `<section class="feature-strip">${pool().slice(0,V===1?4:3).map(d=>`<a href="${href(d)}"><strong>${esc(d.name)}</strong><p>${esc(d.summary)}</p><span>Explore resource →</span></a>`).join('')}</section>`;}
const baseCard=card;
card=function(d){if(V!==2)return baseCard(d);return `<article class="card registry-row"><span class="rank">${String(d.order+1).padStart(2,'0')}</span><span class="monogram">${esc(d.mark)}</span><div class="row-body"><h3><a href="${href(d)}">${esc(d.name)}</a></h3><small>${esc(d.owner)}</small><p>${esc(d.summary)}</p></div><div class="row-meta">${badge(d.category)}<small>${esc(d.license)}</small><a href="${href(d)}">Details ↗</a></div><button class="save" data-save="${d.id}" aria-label="Save ${esc(d.name)}">☆</button><button data-compare="${d.id}">Compare +</button></article>`;};
searchView=function(kind='discover',items=pool(),title){const cats=[...new Set(pool().map(d=>d.category))],types=[...new Set(items.map(d=>d.type))],home=kind==='discover';
 const headlines=[B.id==='lawyer'?'The directory for legal technology,<br>skills, and MCP servers.':'The directory for AI companies,<br>skills, and MCP servers.',B.id==='lawyer'?'Legal technology registry':'AI company registry',B.id==='lawyer'?'Discover The Best<br><span>Legal Technology</span>':'Discover The Best<br><span>AI Building Blocks</span>',B.id==='lawyer'?'LEGAL TECHNOLOGY / INDEX':'AI COMPANY / INDEX'];
return `<section class="reference-hero ${home?'home-hero':''}"><div class="eyebrow">${V===2?'Resource registry':V===3?'● '+pool().length+' RESOURCES · SOURCE SAMPLES':V===4?'SKILLS / MCP / WORKFLOWS':'DISCOVER · CONNECT · BUILD'}</div><h1>${home?headlines[V-1]:esc(title||kind.replaceAll('-',' '))}</h1><p>${B.id==='lawyer'?'Research infrastructure, document automation, skills and integrations for modern legal teams.':'Agents, workflows, skills and infrastructure for building an AI company.'}</p></section><form class="searchbox" id="searchForm"><span aria-hidden="true">⌕</span><input id="search" type="search" aria-label="Search resources" placeholder="${B.search}" value="${esc(state.query)}"><button class="primary">Search</button></form>${home&&V!==4?featured():''}${V===1&&home?`<div class="browse-tiles">${[['skills','Agent Skills','Reusable capabilities for focused tasks.'],['marketplace','Marketplaces','Services and partners for your stack.'],['mcp-servers','MCP Servers','Connect agents to tools and data.']].map(([r,t,p])=>`<a href="#/${r}"><h2>${t} ↗</h2><p>${p}</p></a>`).join('')}</div>`:''}<div class="categories">${['All',...cats].map(c=>`<button class="chip ${state.category===c?'active':''}" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="catalogue"><aside class="filters" id="filters"><p class="filter-title">${V===2?'CATEGORIES & FILTERS':'Refine results'}</p><fieldset><legend>Resource type</legend>${types.map(t=>`<label><input type="checkbox" data-type="${esc(t)}">${esc(t)}</label>`).join('')}</fieldset><fieldset><legend>Collection</legend><label><input id="savedOnly" type="checkbox">Saved resources</label></fieldset><button id="reset">Reset filters</button></aside><section><div class="results-head"><h2>${home?(V===3?'Featured resources':V===2?'Resource index':'Browse resources'):esc(title||'Resources')} <span id="count" class="count"></span></h2><button class="filter-toggle secondary" id="filterToggle" aria-controls="filters" aria-expanded="false">Filters</button><select id="sort" aria-label="Sort resources"><option value="editorial">Directory order</option><option value="az">Name: A–Z</option><option value="type">Resource type</option></select></div><div id="cards" class="cards"></div></section></div>${home?`<section class="home-bottom"><h2>Build your stack, one resource at a time.</h2><p>Explore the technology, inspect its source, and keep the tools that fit your workflow.</p>${link('categories','Browse all categories →')} ${link('hub','Open your workspace →')}</section><section class="faq"><h2>Frequently asked questions</h2>${[['What can I discover here?','Products, skills, repositories, MCP servers and clearly labelled demonstration services.'],['How do I connect a resource?','Open its detail page for the original documentation, runtime and permission context.'],['Can I save a collection?','Save resources to this browser and compare up to three at a time.'],['Are the resources verified?','Public source metadata has been reviewed for the sample records. Security, compatibility and production suitability are not audited.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>`:''}`;};
const baseDetail=detail;
detail=function(d){const brief=`<div class="breadcrumb">${link('discover','Directory')} › ${link('category/'+encodeURIComponent(d.category),esc(d.category))} › ${esc(d.name)}</div>`,actions=`<div class="actions">${external(d.source,'View original source','primary')||link('submit','Prepare a request')}<button class="secondary" data-save="${d.id}" aria-label="Save ${esc(d.name)}">Save ☆</button><button class="secondary" data-compare="${d.id}">Compare +</button></div>`,meta=`<aside class="doc-side">${sourcePanel(d)}<section class="panel"><h3>Categories</h3>${link('category/'+encodeURIComponent(d.category),esc(d.category))}<h3 style="margin-top:24px">Corrections</h3><p>Help keep this resource accurate.</p>${link('report/'+d.id,'Report this listing →')}</section></aside>`,overview=`<h2>${V===4?'README.md':'Overview'}</h2><p>${esc(d.description)}</p><h3>Capabilities</h3><ul>${d.capabilities.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`,tech=`<h2>${V===2?'Connection details':'Technical context'}</h2><table class="metadata">${[['Runtime',d.runtime],['Compatibility',d.compatibility],['Permissions',d.risk],['Maintenance',d.status]].map(([k,v])=>`<tr><th>${k}</th><td>${esc(v||'See original documentation')}</td></tr>`).join('')}</table><h3>Source documentation</h3>${external(d.docs||d.source,'Open setup guide','secondary')||'<p>Fictional demo; no installation package.</p>'}<p>Installation has not been executed or validated in this directory.</p>`,related=`<section class="related"><h2>Related resources</h2><div class="cards">${pool().filter(x=>x.id!==d.id).slice(0,3).map(card).join('')}</div></section>`,title=`<div class="detail-title">${V!==4?`<span class="monogram">${esc(d.mark)}</span>`:''}<div class="eyebrow">${esc(d.type)} · ${esc(d.demo?'Fictional demo':d.category)}</div><h1>${esc(d.name)}</h1><p>${esc(d.summary)}</p>${actions}</div>`;
return brief+`<div class="doc-layout detail-v${V}"><article>${title}${d.status==='Deprecated'||d.status==='Maintenance mode'?`<div class="notice">${esc(d.status)} — ${esc(d.maintenanceNote||'Review the original source before use.')}</div>`:''}${V===2?`<section class="connect-box"><h2>Connect ${esc(d.name)}</h2><div class="detail-tabs"><button data-tab="overview" class="active">Overview</button><button data-tab="technical">Setup & permissions</button></div><div class="code">${esc(d.source||'Fictional demonstration — no live endpoint')}</div></section>`:V===3?'<div class="detail-tabs"><button data-tab="overview" class="active">Overview</button><button data-tab="technical">Technical details</button></div>':''}<section class="panel doc-content" data-pane="overview">${overview}</section><section class="panel doc-content" data-pane="technical">${tech}</section>${V===1?`<section class="panel"><h2>Resource capabilities</h2>${d.capabilities.map(t=>`<details><summary>${esc(t)}</summary><p>See the original maintainer documentation for the current implementation and required permissions.</p></details>`).join('')}</section>`:''}</article>${meta}</div>`+related;};
const additions=['digest','tools','advertise','login','harness','newsletter','learn','blog','hub','leaderboard','cookies','dmca'];routes.push(...additions);
function extraPage(r){const titles={digest:'The technology digest',tools:'Tools for your workflow',advertise:'Reach the people building what’s next.',login:'Your local workspace',harness:'The agent harness',newsletter:'Stay close to what’s next.',learn:'Learn to build your stack',blog:'Field notes',hub:'Your resource workspace',leaderboard:'Resource index',cookies:'Cookie information',dmca:'Rights & corrections'};
const articles=[['Choose a resource','Start with the task, then compare capabilities, ownership and licence evidence.','how-listings-work'],['Connect your stack','Read the runtime, deployment and permission boundaries before connecting tools.','security-and-installation-safety'],['Keep a source trail','Record the original project, licence and maintenance status for every dependency.','provenance-and-licences']];
return `<section class="page-title"><div class="eyebrow">${B.name} / ${r}</div><h1>${titles[r]}</h1><p>${r==='login'?'This HTML preview uses a local workspace. No account or password is required.':r==='advertise'?'A home for useful products, skills and services. Commercial placements are not active in this preview.':r==='newsletter'?'Preview our resource updates. Email subscription is not connected in this local build.':'Explore the resources and practical context behind your next workflow.'}</p></section>${['hub','login'].includes(r)?`<div class="browse-tiles">${[['saved','Saved resources','Your browser-local collection.'],['review','Review queue','Resource submissions prepared in this browser.'],['submit','Add a resource','Save a draft for later review.']].map(([p,t,d])=>`<a href="#/${p}"><h2>${t}</h2><p>${d}</p></a>`).join('')}</div>`:r==='advertise'?`<div class="browse-tiles">${['Directory feature','Resource spotlight','Digest placement'].map(t=>`<a href="#/contact"><h2>${t}</h2><p>Discuss a placement. Pricing and availability have not been set.</p><span>Prepare an enquiry →</span></a>`).join('')}</div>`:['tools','leaderboard'].includes(r)?`<div class="cards">${pool().map(card).join('')}</div>`:['cookies','dmca'].includes(r)?`<article class="prose"><h2>${r==='cookies'?'Local storage':'Report a rights concern'}</h2><p>${r==='cookies'?'This self-contained prototype stores saved resource IDs and review drafts in your browser. It does not use tracking cookies.':'Each resource links to its original maintainer. Prepare a correction request with the listing and supporting source evidence.'}</p>${link(r==='cookies'?'privacy':'contact','Read more →')}</article>`:`<div class="link-grid">${articles.map(([t,p,l],i)=>`<a class="link-tile" href="#/${l}"><small>0${i+1} / RESOURCE GUIDE</small><h2>${t}</h2><p>${p}</p><span>Read guide →</span></a>`).join('')}</div>`}`;}
const coreRender=render;
render=function(){const r=location.hash.split('/')[1]||'discover';if(additions.includes(r)){ $('#main').innerHTML=extraPage(r);document.title=B.name+' — '+r;wireCards();paintCompare();$('#savedCount').textContent=state.saved.length||'';}else coreRender();document.body.dataset.page=r;$$('.ref-nav a').forEach(a=>{if(a.hash==='#/'+r)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$$('[data-tab]').forEach(b=>b.onclick=()=>{$$('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));$$('[data-pane]').forEach(p=>p.hidden=p.dataset.pane!==b.dataset.tab);});if($('[data-tab]'))$$('[data-pane]').forEach(p=>p.hidden=p.dataset.pane!=='overview');};
shell();$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();};window.addEventListener('hashchange',()=>{resetFilters();render();$$('details.mobile-menu,details.nav-drop').forEach(d=>d.open=false);window.scrollTo(0,0);$('#main').focus({preventScroll:true});});render();
